INSERT INTO TB_TRMA_NOTIFICATION
(USER_ID, TYPE_CD, TITLE, CONTENT, PARAM1, PARAM2, LINK_URL, IS_READ, CREATE_DT)
SELECT
    m.USER_ID
    ,'CHAT'
    ,#{senderName}
    ,#{content}
    ,#{senderName}
    ,#{content}
    ,CONCAT('/chat/', #{roomId})
    ,'N'
    ,CURRENT_TIMESTAMP
FROM TB_TRMA_CHAT_MEMBER m
WHERE m.ROOM_ID = #{roomId}
    AND m.USER_ID != #{senderId}

